discrete TouchSubsystem
port:
    event input real DetectCapacitanceChange;
    event output real ValidSignal;
state:
    initial state NoTouchState
        when entry() then
            statehold(0);
        end;
        when receive(DetectCapacitanceChange) then
            transition(TouchState);
        end;
    end;

    state TouchState
        when entry() then
            statehold(0);
        end;
        when receive(DetectCapacitanceChange) then
            transition(NoTouchState);
        out
            send(ValidSignal, 1);
        end;
        when timeover() then
            transition(NoTouchState);
        end;
    end;
end;
end;

discrete SignalProcessingSubsystem
port:
    event input real ValidSignal;
    event output real ProcessedSignal;
    event output real ErrorSignal;
state:
    initial state WaitForSignal
        when entry() then
            statehold(0);
        end;
        when receive(ValidSignal) then
            transition(ProcessSignal);
        end;
    end;

    state ProcessSignal
        when entry() then
            statehold(0);
        end;
        when ProcessCompleted and NoError then
            transition(SignalOutput);
        out
            send(ProcessedSignal, 1);
        end;
        when ProcessCompleted and HasError then
            transition(ErrorState);
        out
            send(ErrorSignal, 1);
        end;
    end;

    state SignalOutput
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(WaitForSignal);
        end;
    end;

    state ErrorState
        when entry() then
            statehold(0);
        end;
        when ErrorHandled then
            transition(WaitForSignal);
        end;
    end;
end;
end;

discrete ControlOutputSubsystem
port:
    event input real ProcessedSignal;
    event output real ControlSignal;
    event output real ErrorSignal;
state:
    initial state WaitForControlSignal
        when entry() then
            statehold(0);
        end;
        when receive(ProcessedSignal) then
            transition(GenerateControlSignal);
        end;
    end;

    state GenerateControlSignal
        when entry() then
            statehold(0);
        end;
        when SignalGenerated and NoError then
            transition(OutputControlSignal);
        out
            send(ControlSignal, 1);
        end;
        when SignalGenerated and HasError then
            transition(ErrorState);
        out
            send(ErrorSignal, 1);
        end;
    end;

    state OutputControlSignal
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(WaitForControlSignal);
        end;
    end;

    state ErrorState
        when entry() then
            statehold(0);
        end;
        when ErrorHandled then
            transition(WaitForControlSignal);
        end;
    end;
end;
end;

